const errorData = $input.item.json;
const execution = errorData.execution || {};
const workflow = errorData.workflow || {};
const error = errorData.execution?.error || {};

return {
  json: {
    workflow_id: workflow.id || 'smm-pipeline',
    workflow_name: workflow.name || 'SMM Pipeline',
    node_name: error.node?.name || 'Unknown Node',
    error_message: error.message || 'Unknown runtime error',
    execution_id: execution.id || '',
    occurred_at: new Date().toISOString()
  }
};

